#include "CategoryPropertiesTask.hpp"
#include <iostream>
using namespace udm;
template<class F>static bool until(F f){const auto end=GetTickCount64()+6000;while(!f()&&GetTickCount64()<end)Sleep(1);return f();}
int wmain(int argc,wchar_t** argv){
 if(argc!=2)return 2;const auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json checks=Json::array();std::string error;
 const auto check=[&](bool ok,const char* name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);};
 try{
  Manager manager(root/L"catalog");manager.state["Settings"]["DownloadFolder"]=utf8((root/L"files").wstring());manager.state["Settings"]["PrivateToken"]="not-for-editor";manager.state["Settings"]["CategoryTypeOverrides"]={{"Video","mp4 mkv"}};
  CategoryPropertiesTask task;auto before=manager.snapshot();task.start(manager);check(until([&]{return task.ready();}),"An owned fresh settings read settles");auto view=task.take();check(view.error.empty()&&!view.saved&&!view.cancelled&&std::find(view.categories.begin(),view.categories.end(),"Other")!=view.categories.end(),"The editor receives current categories without a mutation");check(!view.settings.contains("PrivateToken")&&str(view.settings["CategoryTypeOverrides"],"Video")=="mp4 mkv","Only editor preferences cross the worker boundary, including extension overrides");check(manager.snapshot()==before,"Loading never saves or retargets a download");
  {
   std::promise<void> release;auto gate=release.get_future().share();std::atomic_bool held=false,waiting=false;std::thread writer([&]{Lock lock(manager.mutex);held=true;gate.wait();});struct Join{std::promise<void>& release;std::thread& worker;~Join(){try{release.set_value();}catch(...){}if(worker.joinable())worker.join();}} cleanup{release,writer};check(until([&]{return held.load();}),"A real catalog writer precedes the owned read");
   task.start(manager,{}, {},[&](const char* stage){if(std::string(stage)=="waiting-read")waiting=true;});check(until([&]{return waiting.load();})&&!task.ready()&&!manager.fileInfoDecisionPending,"Read acquisition waits off caller thread without owning the decision guard");task.cancelRead();check(until([&]{return task.ready();})&&task.take().cancelled&&held,"Cancel completes while the catalog writer remains held");release.set_value();writer.join();
  }
  CategoryPropertiesDraft draft{"","Owned category","mp4 mkv","*.example.com",utf8((root/L"custom").wstring()),true};
  {
   std::promise<void> release;auto gate=release.get_future().share();std::atomic_bool held=false,waiting=false,notified=false;std::thread writer([&]{Lock lock(manager.mutex);manager.state["Settings"]["UserAgent"]="Concurrent choice";held=true;gate.wait();});struct Join{std::promise<void>& release;std::thread& worker;~Join(){try{release.set_value();}catch(...){}if(worker.joinable())worker.join();}} cleanup{release,writer};check(until([&]{return held.load();}),"A real writer holds settings before accepted Save");
   task.start(manager,draft,[&]{notified=true;throw std::runtime_error("wake failure");},[&](const char* stage){if(std::string(stage)=="waiting-save")waiting=true;});check(until([&]{return waiting.load();})&&task.saving()&&manager.fileInfoDecisionPending&&!task.ready(),"Accepted Save returns while its worker owns the global decision guard and waits for the model");bool rejected=false;try{task.start(manager);}catch(...){rejected=true;}check(rejected,"A busy editor refuses duplicate commands");task.cancelRead();check(!task.ready()&&task.saving(),"Read cancellation cannot discard an already accepted Save");release.set_value();writer.join();check(until([&]{return notified.load();})&&task.ready()&&manager.fileInfoDecisionPending,"Save publishes before a throwing weak wake and keeps its guard until UI consumption");auto result=task.take();check(result.saved&&result.error.empty()&&result.name==draft.name&&std::find(result.categories.begin(),result.categories.end(),draft.name)!=result.categories.end()&&!manager.fileInfoDecisionPending,"Save returns the accepted name and category cohort and releases its guard");
  }
  check(str(manager.state["Settings"],"UserAgent")=="Concurrent choice"&&yes(manager.state["Settings"]["CategoryRememberLast"],draft.name.c_str()),"An accepted category save preserves concurrent unrelated preferences and remembers its path");
  before=manager.snapshot();task.start(manager,draft);check(until([&]{return task.ready();}),"A duplicate-category Save settles");auto invalid=task.take();check(!invalid.saved&&!invalid.error.empty()&&!manager.fileInfoDecisionPending&&manager.snapshot()==before,"Failed validation rolls back remember settings and retains all prior state");
  manager.fileInfoDecisionPending=true;task.start(manager);Sleep(30);check(!task.ready(),"A read waits for another accepted global decision");task.cancelRead();check(until([&]{return task.ready();})&&task.take().cancelled&&manager.fileInfoDecisionPending,"Cancelling the read never releases somebody else's decision guard");manager.fileInfoDecisionPending=false;
  task.start(manager);check(until([&]{return task.ready();})&&task.take().error.empty(),"The owner can retry after a failed save or cancelled read");task.finish();manager.stop();
 }catch(const std::exception& failure){error=failure.what();}
 atomicText(root/L"results.json",Json{{"passed",error.empty()},{"checks",checks},{"error",error}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<(error.empty()?"passed":error)<<"\n";return error.empty()?0:1;
}
